// Obtener la salida de la IA (string)
const rawOutput = $json.output;

// Comprobacion de seguridad
if (!rawOutput || typeof rawOutput !== 'string') {
  throw new Error('No se encontro una salida valida de la IA para parsear');
}

let parsedOutput;

try {
  parsedOutput = JSON.parse(rawOutput);
} catch (error) {
  throw new Error('No se pudo parsear la salida de la IA como JSON');
}

// Devolver el JSON limpio para los nodos siguientes
return [
  {
    json: parsedOutput
  }
];
